        fullText: '峨眉高出西极天，罗浮直与南溟连。名公绎思挥彩笔，驱山走海置眼前。满堂空翠如可扫，赤城霞气苍梧烟。洞庭潇湘意渺绵，三江七泽情洄沿。惊涛汹涌向何处，孤舟一去迷归年。征帆不动亦不旋，飘如随风落天边。心摇目断兴难尽，几时可到三山巅。西峰峥嵘喷流泉，横石蹙水波潺湲。东崖合沓蔽轻雾，深林杂树空芊绵。此中冥昧失昼夜，隐几寂听无鸣蝉。长松之下列羽客，对坐不语南昌仙。南昌仙人赵夫子，妙年历落青云士。讼庭无事罗众宾，杳然如在丹青里。五色粉图安足珍。真仙可以全吾身。若待功成拂衣去，武陵桃花笑杀人。',
