        fullText: '连昌宫中满宫竹，岁久无人森似束。又有墙头千叶桃，风动落花红蔌蔌。宫边老翁为余泣：“小年进食曾因入。上皇正在望仙楼，太真同凭阑干立。楼上楼前尽珠翠，炫转荧煌照天地。归来如梦复如痴，何暇备言宫里事。初届寒食一百六，店舍无烟宫树绿。夜半月高弦索鸣，贺老琵琶定场屋。力士传呼觅念奴，念奴潜伴诸郎宿。须臾觅得又连催，特敕街中许燃烛。春娇满眼睡红绡，掠削云鬟旋装束。飞上九天歌一声，二十五郎吹管笛。逡巡大遍凉州彻，色色龟兹轰录续。李谟压笛傍宫墙，偷得新翻数般曲。平明大驾发行宫，万人歌舞途路中。百官队仗避岐薛，杨氏诸姨车斗风。明年十月东都破，御路犹存禄山过。驱令供顿不敢藏，万姓无声泪潜堕。',
        background: '辞典补录；原辞典未系年，暂附此节点，系年与地点待考。',
