        year: 829,
        yearLabel: '大和三年',
        placeId: 'lishangyin-n2',
        excerpt: '衮师我骄儿，美秀乃无匹。文葆未周晬，固已知六七。',
        fullText: '衮师我骄儿，美秀乃无匹。文葆未周晬，固已知六七。四岁知姓名，眼不视梨栗。交朋颇窥观，谓是丹穴物。前朝尚器貌，流品方第一。不然神仙姿，不尔燕鹤骨。安得此相谓。欲慰衰朽质。青春妍和月，朋戏浑甥侄。绕堂复穿林，沸若金鼎溢。门有长者来，造次请先出。客前问所须，含意不吐实。归来学客面，䦱败秉爷笏。或谑张飞胡，或笑邓艾吃。豪鹰毛崱屴，猛马气佶傈。截得青筼筜，骑走恣唐突。忽复学参军，按声唤苍鹘。又复纱灯旁，稽首礼夜佛。仰鞭罥蛛网，俯首饮花蜜。欲争蛱蝶轻，未谢柳絮疾。阶前逢阿姊，六甲颇输失。凝走弄香奁，拔脱金屈戌。抱持多反倒，威怒不可律。曲躬牵窗网，衉唾拭琴漆。有时看临书，挺立不动膝。古锦请裁衣，玉轴亦欲乞。请爷书春胜，春胜宜春日。芭蕉斜卷笺，辛夷低过笔。爷昔好读书，恳苦自著述。憔悴欲四十，无肉畏蚤虱。儿慎勿学爷，读书求甲乙。穰苴司马法，张良黄石术。便为帝王师，不假更纤悉。况今西与北，羌戎正狂悖。诛赦两未成，将养如痼疾。儿当速成大，探雏入虎穴。当为万户侯，勿守一经帙。',
        background: '辞典补录；原辞典未系年，暂附此节点，系年与地点待考。',
