        excerpt: '红杏飘香，柳含烟翠拖轻缕。水边朱户。',
        fullText: '红杏飘香，柳含烟翠拖轻缕。水边朱户。尽卷黄昏雨。烛影摇风，一枕伤春绪。归不去。凤楼何处。芳草迷归路。东坡才大如海，其词堂庑亦大。如“有情风万里卷潮来，无情送潮归”，固然极富创新之局面。而如“枝上柳绵吹又少，天涯何处无芳草”，则又深具传统之神理。此首《点绛唇》亦然。',
