        fullText: '山抹微云，天连衰草，画角声断谯门。暂停征棹，聊共引离尊。多少蓬莱旧事，空回首，烟霭纷纷。斜阳外，寒鸦万点，流水绕孤村。销魂。当此际，香囊暗解，罗带轻分。谩赢得青楼，薄幸名存。此去何时见也，襟袖上，空惹啼痕。伤情处，高城望断，灯火已黄昏。有不少词调，开头两句八个字，便是一副工致美妙的对联。宋代名家，大抵皆向此等处见工夫，逞文采。诸如“做冷欺花，将烟困柳”,“叠鼓夜寒，垂灯春浅”……一时也举他不尽。这好比名角出台，绣帘揭处，一个亮相，丰采精神，能把全场“笼罩”住。',
