        fullText: '条风布暖，霏雾弄晴，池塘遍满春色。正是夜堂无月，沉沉暗寒食。梁间燕，前社客。似笑我、闭门愁寂。乱花过，隔院芸香，满地狼藉。长记那回时，邂逅相逢，郊外驻油壁。又见汉宫传烛，飞烟五侯宅。青青草，迷路陌。强载酒、细寻前迹。市桥远，柳下人家，犹自相识。清真词情深入骨。',
