        excerpt: '对宿烟收，春禽静，飞雨时鸣高屋。墙头青玉斾，洗铅霜都尽，嫩梢相触。',
        fullText: '对宿烟收，春禽静，飞雨时鸣高屋。墙头青玉斾，洗铅霜都尽，嫩梢相触。润逼琴丝，寒侵枕障，虫网吹粘帘竹。邮亭无人处，听檐声不断，困眠初熟。奈愁极频惊，梦轻难记，自怜幽独。行人归意速。最先念、流潦妨车毂。怎奈向、兰成憔悴，卫玠清羸，等闲时、易伤心目。未怪平阳客，双泪落、笛中哀曲。况萧索、青芜国。红糁铺地，门外荆桃如菽。夜游共谁秉烛。',
