        placeId: 'zhoubangyan-n4',
        excerpt: '晓阴重，霜凋岸草，雾隐城堞。南陌脂车待发，东门帐饮乍阕。',
        fullText: '晓阴重，霜凋岸草，雾隐城堞。南陌脂车待发，东门帐饮乍阕。正拂面垂杨堪揽结。掩红泪、玉手亲折。念汉浦离鸿去何许，经时信音绝。情切。望中地远天阔。向露冷风清无人处，耿耿寒漏咽。嗟万事难忘，唯是轻别。翠樽未竭，凭断云、留取西楼残月。罗带光销纹衾叠，连环解，旧香顿歇。怨歌永、琼壶敲尽缺。恨春去、不与人期，弄夜色，空馀满地梨花雪。',
