        fullText: '灰暖香融销永昼。蒲萄架上春藤秀。曲角栏干群雀斗。清明后。风梳万缕亭前柳。日照钗梁光欲溜。循阶竹粉沾衣袖。拂拂面红如著酒。沉吟久。昨宵正是来时候。爱情本是清真词乐章的主旋律之一。然而爱情的艺术表现在清真集的许多篇章中，则给人以日新又新之感。清真词的艺术魅力正在于此。',
