        fullText: '黄庆长夜泛鉴湖，有怀归之曲，课予和之。夜深客子移舟处，两两沙禽惊起。红衣入桨，青灯摇浪，微凉意思。把酒临风，不思归去，有如此水。况茂陵游倦，长干望久，芳心事、箫声里。屈指归期尚未。鹊南飞、有人应喜。画阑桂子，留香小待，提携影底。我已情多，十年幽梦，略曾如此。甚谢郎、也恨飘零，解道月明千里。白石平生怀人情深，大自然之一草一木，人世间之寻常小事，往往牵发其情而不能自已。如《江梅引》:“见梅枝，忽相思。',
