        excerpt: '晴丝牵绪乱。对沧江斜日，花飞人远。',
        fullText: '晴丝牵绪乱。对沧江斜日，花飞人远。垂杨暗吴苑。正旗亭烟冷，河桥风暖。兰情蕙盼。惹相思，春根酒畔。又争知、吟骨萦销，渐把旧衫重剪。凄断。流红千浪，缺月孤楼，总难留燕。歌尘凝扇。待凭信，拌分钿。试挑灯欲写，还依不忍，笺幅偷和泪卷。寄残云剩雨蓬莱，也应梦见。这一首词在梦窗词中是别具一格的，上阕写江湖漂泊的文人苦相思。下阕写女子怀念他的一片幽怨。在用语上雅俗融一，也属于不隐晦难懂的一类，并且和曲有相通的地方。梦窗当时当是旅住吴门（苏州），季节正逢寒食。词写的是距离美，反映一种彼此因消息难通而产生了隔膜的猜疑心理。相反相成，是递进一步写法。',
