        excerpt: '燕亡久矣，京口适见似人，怅怨有感。南楼坠燕。',
        fullText: '燕亡久矣，京口适见似人，怅怨有感。南楼坠燕。又灯晕夜凉，疏帘空卷。叶吹暮喧，花露晨晞秋光短。当时明月娉婷伴。怅客路、幽扃俱远。雾鬟依约，除非照影，镜空不见。别馆。秋娘乍识，似人处、最在双波凝盼。旧色旧香，闲雨闲云情终浅。丹青谁画真真面，便只作、梅花频看。更愁花变梨霙，又随梦散。',
