        placeId: 'wuwengying-n3',
        excerpt: '紫骝嘶冻草，晓云锁，岫眉颦。正蕙雪初消，松腰玉瘦，憔悴真真。',
        fullText: '紫骝嘶冻草，晓云锁，岫眉颦。正蕙雪初消，松腰玉瘦，憔悴真真。轻藜渐穿险磴，步荒苔、犹认瘗花痕。千古兴亡旧恨，半丘残日孤云。开尊，重吊吴魂。岚翠冷，洗微醺。问几曾夜宿，月明起看，剑水星纹。登临总成去客，更软红、先有探芳人。回首沧波故苑，落梅烟雨黄昏。',
