        fullText: '梅梢腊尽春归了。毕竟春寒少。乱山残烛雪和风。犹胜阴山海上窖群中。年光老去才情在。唯有华风改。醉中幸自不曾愁。谁唱春花秋叶泪偷流。情知是梦无凭了。好梦依然少。单于吹尽五更风。谁见梅花如泪不言中。儿童问我今何在。烟雨楼台改。江山画出古今愁。人与落花何处水空流。',
