        fullText: '送春去，春去人间无路。秋千外、芳草连天，谁遣风沙暗南浦。依依甚意绪。漫忆海门飞絮。乱鸦过，斗转城荒，不见来时试灯处。春去，最谁苦？但箭雁沉边，梁燕无主，杜鹃声里长门暮。想玉树凋土，泪盘如露。咸阳送客屡回顾，斜日未能度。春去，尚来否？正江令恨别，庾信愁赋。（二人皆北去）苏堤尽日风和雨。叹神游故国，花记前度。人生流落，顾孺子，共夜语。',
