        fullText: '禁烟湖上薄游，施中山赋词甚佳，余因次其韵。盖平时游舫，至午后则尽入里湖，抵暮始出，断桥小驻而归，非习于游者不知也。故中山极击节余“闲却半湖春色”之句，谓能道人之所未云。禁苑东风外，飏暖丝晴絮，春思如织。燕约莺期，恼芳情、偏在翠深红隙。漠漠香尘隔。沸十里乱弦丛笛。看画船尽入西泠，闲却半湖春色。柳陌。新烟凝碧。映帘底宫眉，堤上游勒。轻暝笼寒，怕梨云梦冷，杏香愁幂。歌管酬寒食。奈蝶怨良宵岑寂。正满湖碎月摇花，怎生去得。',
