        placeId: 'zhoumi-n2',
        excerpt: '槐薰忽送清商怨，依稀正闻还歇。故苑愁深，危弦调苦，前梦蜕痕枯叶。',
        fullText: '槐薰忽送清商怨，依稀正闻还歇。故苑愁深，危弦调苦，前梦蜕痕枯叶。伤情念别。是几度斜阳，几回残月。转眼西风，一襟幽恨向谁说。轻鬟犹记动影，翠蛾应妒我，双鬓如雪。枝冷频移，叶疏犹抱，孤负好秋时节。凄凄切切。渐迤逦黄昏，砌蛩相接。露洗馀悲，暮烟声更咽。',
