        excerpt: '长安独客，又见西风，素月丹枫，凄然其为秋也。因调夹钟羽一解。',
        fullText: '长安独客，又见西风，素月丹枫，凄然其为秋也。因调夹钟羽一解。烟水阔。高林弄残照，晚蜩凄切。碧砧度韵，银床飘叶。衣湿桐阴露冷，采凉花，时赋秋雪。叹轻别，一襟幽事，砌蛩能说。客思吟商还怯。怨歌长、琼壶暗缺。翠扇恩疏，红衣香褪，翻成消歇。玉骨西风，恨最恨、闲却新凉时节。楚箫咽，谁倚西楼淡月。',
