        fullText: '遥望具区，渺如烟云，洞庭、缥缈诸峰，矗矗献状，盖王右丞、李将军著色画也。松风怒号，暝色四起，使人浩然忘归。慨然怀古，高歌举白，不知身世为何如也。溪山不老，临赏无穷，后之视今，当有契余言者。因大书山楹，以纪来游。波影摇涟甃。趁熏风、一舸来时，翠阴清昼。去郭轩楹才数里，藓磴松关云岫。快屐齿筇枝先后。空半危亭堪聚远，看洞庭缥缈争奇秀。人自老，景如旧。来帆去棹还知否。问古今、几度斜阳，几番回首。晚色一川谁管领，都付雨荷烟柳。知我者、燕朋鸥友。笑拍阑干呼范蠡，甚平吴、却倩垂纶手。吁万古，付卮酒。',
